import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.security.SecureRandom;
import java.security.spec.InvalidKeySpecException;
import java.util.Base64;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import javax.crypto.SecretKeyFactory;
import javax.crypto.spec.PBEKeySpec;

public class Main {
    private static final int SALT_BYTES = 16;
    private static final int ITERATIONS = 210000;
    private static final int KEY_LENGTH = 256;
    private static final SecureRandom RANDOM = new SecureRandom();
    private static final Map<String, StoredCredential> USERS = new ConcurrentHashMap<>();

    private static final class StoredCredential {
        private final String username;
        private final String salt;
        private final String hash;

        StoredCredential(String username, String salt, String hash) {
            this.username = username;
            this.salt = salt;
            this.hash = hash;
        }
    }

    public static boolean registerUser(String username, String password) {
        if (!isValidInput(username, password)) {
            return false;
        }
        String normalizedUsername = normalizeUsername(username);
        String salt = generateSalt();
        String hash = hashPassword(password, salt);
        return USERS.putIfAbsent(normalizedUsername, new StoredCredential(normalizedUsername, salt, hash)) == null;
    }

    public static boolean authenticateUser(String username, String password) {
        if (!isValidInput(username, password)) {
            return false;
        }
        StoredCredential credential = USERS.get(normalizeUsername(username));
        if (credential == null) {
            // Perform a dummy hash to reduce timing differences between existing/non-existing users.
            hashPassword(password, generateSalt());
            return false;
        }
        String candidateHash = hashPassword(password, credential.salt);
        return constantTimeEquals(candidateHash, credential.hash);
    }

    public static boolean changePassword(String username, String oldPassword, String newPassword) {
        if (!authenticateUser(username, oldPassword)) {
            return false;
        }
        if (!isValidInput(username, newPassword)) {
            return false;
        }
        String normalizedUsername = normalizeUsername(username);
        String salt = generateSalt();
        String hash = hashPassword(newPassword, salt);
        USERS.put(normalizedUsername, new StoredCredential(normalizedUsername, salt, hash));
        return true;
    }

    public static boolean removeUser(String username) {
        if (username == null) {
            return false;
        }
        return USERS.remove(normalizeUsername(username)) != null;
    }

    public static boolean userExists(String username) {
        if (username == null) {
            return false;
        }
        return USERS.containsKey(normalizeUsername(username));
    }

    public static void clearAllUsers() {
        USERS.clear();
    }

    private static boolean isValidInput(String username, String password) {
        return username != null && password != null && !username.trim().isEmpty() && !password.isEmpty();
    }

    private static String normalizeUsername(String username) {
        return username.trim().toLowerCase(java.util.Locale.ROOT);
    }

    private static String generateSalt() {
        byte[] salt = new byte[SALT_BYTES];
        RANDOM.nextBytes(salt);
        return Base64.getEncoder().encodeToString(salt);
    }

    private static String hashPassword(String password, String salt) {
